(function () {
  var KEY = "soulMilestones";
  var MILESTONES = [
    { id: "m1", power: 1000,  label: "自动战斗加速 2x",  desc: "战斗速度永久提升" },
    { id: "m2", power: 5000,  label: "离线收益上限 12h",  desc: "离线收益上限从 6 小时提升到 12 小时" },
    { id: "m3", power: 20000, label: "必杀充能加速",     desc: "每次攻击充能 +12%（原 8%）" }
  ];
  var state = null;
  function load() {
    try { state = JSON.parse(localStorage.getItem(KEY) || "{}"); } catch (e) { state = {}; }
    if (!state || typeof state !== "object") state = {};
  }
  function save() { try { localStorage.setItem(KEY, JSON.stringify(state)); } catch (e) {} }
  load();
  window.milestoneState = { get state() { return state; } };
  window.milestoneUnlocked = function (id) { return !!state[id]; };
  window.checkMilestones = function () {
    if (typeof powerScore !== "function") return;
    var power = powerScore();
    var changed = false;
    MILESTONES.forEach(function (m) {
      if (!state[m.id] && power >= m.power) {
        state[m.id] = true;
        changed = true;
        if (typeof showTutorialTip === "function") showTutorialTip("里程碑达成：" + m.label);
      }
    });
    if (changed) { save(); renderMilestonePanel(); }
  };
  window.milestoneBonus = function () {
    return {
      ultCharge: state.m3 ? 12 : 8,
      offlineCapH: state.m2 ? 12 : 6,
      battleSpeed: state.m1 ? 2 : 1
    };
  };
  function renderMilestonePanel() {
    var box = document.getElementById("milestone-list");
    if (!box) return;
    var power = typeof powerScore === "function" ? powerScore() : 0;
    var html = '<div class="ms-power">当前战力：<strong>' + power + '</strong></div>';
    MILESTONES.forEach(function (m) {
      var unlocked = !!state[m.id];
      var pct = Math.min(100, Math.floor(power / m.power * 100));
      html += '<div class="ms-item' + (unlocked ? " on" : "") + '">' +
        '<div class="ms-row"><span class="ms-label">' + m.label + '</span>' +
        '<span class="ms-req">' + (unlocked ? "已解锁" : power + "/" + m.power) + '</span></div>' +
        '<div class="ms-bar"><div class="ms-fill" style="width:' + (unlocked ? 100 : pct) + '%"></div></div>' +
        '<div class="ms-desc">' + m.desc + '</div>' +
        '</div>';
    });
    box.innerHTML = html;
  }
  window.renderMilestonePanel = renderMilestonePanel;
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", function(){ setTimeout(function(){ renderMilestonePanel(); setInterval(function(){ if (typeof gameState !== "undefined" && gameState) checkMilestones(); }, 5000); }, 2000); });
  } else {
    setTimeout(function(){ renderMilestonePanel(); setInterval(function(){ if (typeof gameState !== "undefined" && gameState) checkMilestones(); }, 5000); }, 2000);
  }
})();
