(function () {
  var KEY = "soulLastActive";
  var DAY_MS = 86400000;
  var last = 0;
  try { last = parseInt(localStorage.getItem(KEY) || "0", 10) || 0; } catch (e) {}
  var daysAway = last ? Math.floor((Date.now() - last) / DAY_MS) : 0;
  window.comebackInfo = { daysAway: daysAway, last: last };
  var REWARDS = {
    1: { gold: 3000,  soul: 0, label: "军队等你很久了", desc: "离线收益翻倍" },
    3: { gold: 10000, soul: 1, label: "你的军队想念你", desc: "赠送 1 个灵魂" },
    7: { gold: 30000, soul: 3, label: "王者归来",     desc: "离线收益三倍 + 回归专属奖励" }
  };
  function pickTier(d) {
    if (d >= 7) return 7;
    if (d >= 3) return 3;
    if (d >= 1) return 1;
    return 0;
  }
  window.showComeback = function () {
    var tier = pickTier(daysAway);
    if (!tier) return;
    var r = REWARDS[tier];
    if (document.getElementById("comeback-overlay")) return;
    var ov = document.createElement("div");
    ov.id = "comeback-overlay";
    ov.innerHTML =
      '<div class="cb-card">' +
        '<div class="cb-icon ui-ic" data-ic="party-popper"></div>' +
        '<div class="cb-title">' + r.label + '</div>' +
        '<div class="cb-days">你离开了 ' + daysAway + ' 天</div>' +
        '<div class="cb-reward">' +
          '<div class="cb-reward-row"><span class="ui-ic" data-ic="two-coins"></span><strong>' + (typeof calcGoldReward === "function" ? Math.floor(calcGoldReward(r.gold)) : r.gold) + '</strong> 金币</div>' +
          (r.soul ? '<div class="cb-reward-row"><span class="ui-ic" data-ic="sparkles"></span><strong>' + r.soul + '</strong> 灵魂</div>' : '') +
        '</div>' +
        '<div class="cb-desc">' + r.desc + '</div>' +
        '<button class="cb-claim" id="cb-claim">领取回归奖励</button>' +
      '</div>';
    document.body.appendChild(ov);
    if (typeof renderUIIcons === "function") renderUIIcons(ov);
    document.getElementById("cb-claim").addEventListener("click", function () {
      if (typeof addPlayerGold === "function") addPlayerGold(r.gold);
      if (r.soul && typeof gameState !== "undefined" && Array.isArray(gameState[45])) {
        var idx = Math.floor(Math.random() * 3);
        gameState[45][idx] += r.soul;
        gameState[50] = (gameState[50] || 0) + r.soul;
        if (typeof renderMorality === "function") renderMorality();
      }
      if (typeof saveGame === "function") saveGame(gameState);
      ov.remove();
    });
  };
  window.touchLastActive = function () {
    try { localStorage.setItem(KEY, String(Date.now())); } catch (e) {}
  };
  setInterval(window.touchLastActive, 30000);
  window.addEventListener("beforeunload", window.touchLastActive);
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", function(){ setTimeout(function(){ if (window.__gameReady) window.showComeback(); }, 2600); });
  } else {
    setTimeout(function(){ if (window.__gameReady) window.showComeback(); }, 2600);
  }
})();
