(function () {
  var KEY = "soulEndlessTower";
  function weekKey() {
    var d = new Date();
    var onejan = new Date(d.getFullYear(), 0, 1);
    var week = Math.ceil(((d - onejan) / 86400000 + onejan.getDay() + 1) / 7);
    return d.getFullYear() + "-W" + week;
  }
  var state = null;
  function load() {
    try { state = JSON.parse(localStorage.getItem(KEY) || "null"); } catch (e) { state = null; }
    var wk = weekKey();
    if (!state || state.week !== wk) {
      state = { week: wk, best: 0, current: 0, active: false, claimed: false };
      save();
    }
  }
  function save() { try { localStorage.setItem(KEY, JSON.stringify(state)); } catch (e) {} }
  load();
  window.towerState = { get state() { return state; } };
  window.startTower = function () {
    if (typeof gameState === "undefined") return;
    state.active = true;
    state.current = 0;
    save();
    window.__towerReturnStage = gameState[9];
    try { localStorage.setItem("soulTowerReturnStage", String(gameState[9])); } catch (e) {}
    gameState[9] = 0;
    if (typeof openStage === "function") openStage(0);
    if (typeof showTutorialTip === "function") showTutorialTip("无尽塔开始！尽可能推进更多关卡");
    closeTowerPanel();
  };
  window.onTowerStageClear = function () {
    if (!state.active) return;
    state.current += 1;
    if (state.current > state.best) { state.best = state.current; save(); }
  };
  window.endTower = function () {
    if (!state.active) return;
    state.active = false;
    save();
    try { localStorage.removeItem("soulTowerReturnStage"); } catch (e) {}
    if (typeof gameState !== "undefined" && window.__towerReturnStage != null) {
      gameState[9] = window.__towerReturnStage;
      if (typeof openStage === "function") openStage(gameState[9]);
    }
    if (typeof showTutorialTip === "function") showTutorialTip("无尽塔结束：本周最佳 " + state.best + " 层");
    openTowerPanel();
  };
  window.towerReward = function (floor) {
    var tiers = [
      { min: 5,  gold: 5000,  soul: 1 },
      { min: 10, gold: 15000, soul: 2 },
      { min: 20, gold: 40000, soul: 4 },
      { min: 30, gold: 100000, soul: 8 }
    ];
    var best = 0;
    for (var i = 0; i < tiers.length; i++) if (floor >= tiers[i].min) best = tiers[i];
    return best;
  };
  window.openTowerPanel = function () {
    var ov = document.getElementById("tower-overlay");
    if (ov) { ov.remove(); return; }
    ov = document.createElement("div");
    ov.id = "tower-overlay";
    var reward = towerReward(state.best);
    var canClaim = reward && !state.claimed;
    var html = '<div class="tw-card">' +
      '<div class="tw-title">无尽塔</div>' +
      '<div class="tw-week">' + state.week + ' · 每周一刷新</div>' +
      '<div class="tw-stats">' +
        '<div class="tw-stat"><span class="tw-stat-label">本周最佳</span><span class="tw-stat-val">' + state.best + ' 层</span></div>' +
        '<div class="tw-stat"><span class="tw-stat-label">本次进度</span><span class="tw-stat-val">' + state.current + ' 层</span></div>' +
      '</div>' +
      (state.active
        ? '<button class="tw-btn tw-end" id="tw-end">结束挑战并结算</button>'
        : '<button class="tw-btn tw-start" id="tw-start">开始挑战</button>') +
      (reward ? '<div class="tw-reward">' + (state.claimed ? "本周奖励已领取" : (canClaim ? "可领取：" + (typeof calcGoldReward === "function" ? Math.floor(calcGoldReward(reward.gold)) : reward.gold) + " 金币 + 灵魂 ×" + reward.soul : "")) + '</div>' : '<div class="tw-reward">达到 5 层开始有奖励</div>') +
      (canClaim ? '<button class="tw-btn tw-claim" id="tw-claim">领取奖励</button>' : '') +
      '<button class="tw-close" id="tw-close">关闭</button>' +
      '</div>';
    ov.innerHTML = html;
    document.body.appendChild(ov);
    document.getElementById("tw-close").addEventListener("click", closeTowerPanel);
    var start = document.getElementById("tw-start");
    if (start) start.addEventListener("click", startTower);
    var end = document.getElementById("tw-end");
    if (end) end.addEventListener("click", endTower);
    var claim = document.getElementById("tw-claim");
    if (claim) claim.addEventListener("click", function () {
      if (!reward || state.claimed) return;
      state.claimed = true;
      save();
      if (typeof addPlayerGold === "function") addPlayerGold(reward.gold);
      if (typeof gameState !== "undefined" && Array.isArray(gameState[45])) {
        var idx = Math.floor(Math.random() * 3);
        gameState[45][idx] += reward.soul;
        gameState[50] = (gameState[50] || 0) + reward.soul;
        if (typeof renderMorality === "function") renderMorality();
      }
      if (typeof saveGame === "function") saveGame(gameState);
      closeTowerPanel();
      setTimeout(openTowerPanel, 100);
    });
  };
  function closeTowerPanel() { var o = document.getElementById("tower-overlay"); if (o) o.remove(); }
  function recoverTowerStage() {
    try {
      var rs = localStorage.getItem("soulTowerReturnStage");
      if (rs == null) return;
      localStorage.removeItem("soulTowerReturnStage");
      var stage = parseInt(rs, 10);
      if (isNaN(stage)) return;
      if (typeof gameState !== "undefined" && gameState) {
        gameState[9] = stage;
        if (state && state.active) { state.active = false; save(); }
        if (typeof openStage === "function") openStage(stage);
        if (typeof saveGame === "function") saveGame(gameState);
      }
    } catch (e) {}
  }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", function(){ setTimeout(recoverTowerStage, 2400); });
  } else {
    setTimeout(recoverTowerStage, 2400);
  }
})();
