(function () {
  var FAMILY = {
    1: "tactic", 5: "tactic", 10: "tactic",
    2: "offense", 3: "offense", 7: "offense", 8: "offense", 9: "offense", 11: "offense",
    4: "defense", 6: "defense"
  };
  var THRESHOLD = { offense: 3, defense: 2, tactic: 3 };
  var BONUS = {
    offense: { atk: 0.12, desc: "进攻系·全体伤害 +12%" },
    defense: { def: 0.10, desc: "防守系·受到伤害 -10%" },
    tactic:  { atk: 0.08, desc: "战术系·全体伤害 +8%" }
  };
  window.TRAIT_FAMILY = FAMILY;
  window.getActiveFamilies = function (raceKey, aliveArr) {
    var counts = { offense: 0, defense: 0, tactic: 0 };
    if (typeof getTrait !== "function" || !Array.isArray(aliveArr)) return counts;
    for (var i = 0; i < aliveArr.length; i++) {
      if ((aliveArr[i] || 0) <= 0) continue;
      var fam = FAMILY[getTrait(raceKey, i)];
      if (fam) counts[fam]++;
    }
    return counts;
  };
  window.getAtkSetMultiplier = function (raceKey, aliveArr) {
    var c = getActiveFamilies(raceKey, aliveArr);
    var mul = 1;
    if (c.offense >= THRESHOLD.offense) mul *= (1 + BONUS.offense.atk);
    if (c.tactic >= THRESHOLD.tactic) mul *= (1 + BONUS.tactic.atk);
    return mul;
  };
  window.getDefSetMultiplier = function (raceKey, aliveArr) {
    var c = getActiveFamilies(raceKey, aliveArr);
    var mul = 1;
    if (c.defense >= THRESHOLD.defense) mul *= (1 - BONUS.defense.def);
    return mul;
  };
  window.getActiveSetDescs = function (raceKey, aliveArr) {
    var c = getActiveFamilies(raceKey, aliveArr);
    var out = [];
    if (c.offense >= THRESHOLD.offense) out.push(BONUS.offense.desc);
    if (c.defense >= THRESHOLD.defense) out.push(BONUS.defense.desc);
    if (c.tactic >= THRESHOLD.tactic) out.push(BONUS.tactic.desc);
    return out;
  };
})();
