      html += '<div class="cm-item' + (done ? " done" : "") + '"><span class="cm-label">' + m.label + '</span><span class="cm-prog">' + Math.min(cur, m.at) + "/" + m.at + (done ? " ✓" : "") + '</span><div class="cm-bar"><div class="cm-fill" style="width:' + pct + '%"></div></div></div>';
